@block RigidBody2D begin
    @ports p::Power{Planar}, [frame = "body"]
    @parameters begin
        m::Real = 1.0, [unit = "kg", min = 0, description = "Body mass"]
        J::Real = 0.01, [unit = "kg*m^2", min = 0, description = "Moment of inertia about the body z axis"]
    end
    # Per-component units differ (torque impulse vs linear momentum), so the unit is left
    # open here and supplied component-wise by the compiler (J-MB2).
    @variables P::Vec{3} = [0.0, 0.0, 0.0], [state = :prefer, description = "Momentum"]
    @equations begin
        # The numeric core is component-wise (D-MB10); M lives only in I (D-MB3).
        for k in 1:3
            ddt(P[k]) ~ p.e[k]
        end
        p.f[1] ~ P[1] / J
        p.f[2] ~ P[2] / m
        p.f[3] ~ P[3] / m
    end
    @causality p => :flow_out
end
